class Solution {
  private static final long CAP = 2_000_000_000_000_000L;

  private static long mul(long a, long b) {
    if (a == 0 || b == 0) return 0;
    return a > CAP / b ? CAP : Math.min(CAP, a * b);
  }

  public int[] permute(int n, long k) {
    long[] fact = new long[n + 1];
    fact[0] = 1;
    for (int i = 1; i <= n; i++) fact[i] = mul(fact[i - 1], i);
    boolean[] used = new boolean[n + 1];
    int[] res = new int[n];
    int odd = (n + 1) / 2, even = n / 2;
    for (int pos = 0; pos < n; pos++) {
      int chosen = -1;
      for (int x = 1; x <= n; x++) {
        if (used[x] || (pos > 0 && (x & 1) == (res[pos - 1] & 1))) continue;
        int o = odd - (x & 1), e = even - (1 - (x & 1));
        long ways;
        if (o + e == 0) ways = 1;
        else if ((x & 1) == 1) ways = (e == o || e == o + 1) ? mul(fact[o], fact[e]) : 0;
        else ways = (o == e || o == e + 1) ? mul(fact[o], fact[e]) : 0;
        if (k <= ways) {
          chosen = x;
          odd = o;
          even = e;
          break;
        }
        k -= ways;
      }
      if (chosen < 0) return new int[0];
      used[chosen] = true;
      res[pos] = chosen;
    }
    return res;
  }
}
